def compute(vars):
    cash_paid = vars["v1"]
    aggregate_purchase_price = vars["v2"]

    if aggregate_purchase_price == 0:
        return None

    value = cash_paid / aggregate_purchase_price
    return {
        "value": value,
        "trace": {
            "cash_paid": cash_paid,
            "aggregate_purchase_price": aggregate_purchase_price,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
